The API sends one message per request. To message many recipients, loop with a delay: async function sendBulkMessages(token, device, recipients, message, options = {}) { const { delayMs = 2000, onProgress = null, onError = null } = options; const results = []; let sent = 0; let failed = 0; for (let i = 0; i < recipients.length; i++) { const receiver = recipients[i]; try { const result = await sendTextMessage(token, device, receiver, message); results.push({ receiver, success: true, messageId: result.data.id, createdAt: result.data.created_at }); sent++; onProgress?.({ sent, failed, total: recipients.length, current: receiver }); } catch (error) { results.push({ receiver, success: false, error: error.message }); failed++; onError?.(receiver, error.message); } if (i < recipients.length - 1) await new Promise((resolve) => setTimeout(resolve, delayMs)); } return { results, summary: { sent, failed, total: recipients.length } }; } const bulkResults = await sendBulkMessages( 'YOUR_API_TOKEN', '6281234567890', ['6289876543210', '6287654321098', '6285432109876'], '📢 *Important Update*

Our services will be updated tonight from 2-4 AM.

Sorry for any inconvenience! 🙏', { delayMs: 3000, onProgress: (p) => console.log(`Progress: ${p.sent}/${p.total} sent (${p.failed} failed)`), onError: (receiver, error) => console.warn(`Failed to send to ${receiver}: ${error}`), }, ); console.log('Bulk messaging completed:', bulkResults.summary); Personalized messages work the same way, with the text built per contact: async function sendPersonalizedMessages(token, device, contacts) { const results = []; for (const contact of contacts) { const text = `Hi ${contact.name}! 👋

Thanks for being a valued customer. Your account status: ${contact.status}

Questions? Just reply! 💬`; try { const result = await sendTextMessage(token, device, contact.phone, text); results.push({ ...contact, success: true, messageId: result.data.id }); } catch (error) { results.push({ ...contact, success: false, error: error.message }); } await new Promise((resolve) => setTimeout(resolve, 2000)); } return results; } const personalizedResults = await sendPersonalizedMessages('YOUR_API_TOKEN', '6281234567890', [ { name: 'John Doe', phone: '6289876543210', status: 'Active' }, { name: 'Jane Smith', phone: '6287654321098', status: 'Premium' }, ]); console.log('Personalized messages sent:', personalizedResults);

async function sendMultipleFiles(token, device, receiver, files, delayMs = 2000) { const results = []; for (const file of files) { try { const result = await sendFileMessage(token, device, receiver, file.url, file.name, file.caption); results.push({ file: file.name, success: true, messageId: result.data.id }); } catch (error) { results.push({ file: file.name, success: false, error: error.message }); } if (delayMs > 0) await new Promise((resolve) => setTimeout(resolve, delayMs)); // pause between files } return results; } const files = [ { name: 'contract.pdf', url: 'https://docs.example.com/contract.pdf', caption: '📋 Service Contract

Please review and sign.', }, { name: 'invoice.pdf', url: 'https://billing.example.com/invoice.pdf', caption: '💳 Invoice #12345

Payment due: Dec 30, 2024', }, ]; const results = await sendMultipleFiles('YOUR_API_TOKEN', '6281234567890', '6289876543210', files); console.log('Batch send results:', results);
